    b = Builder()
    V(b, 33, 51, 'آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) اُن (ازواج) میں سے جس کو چاہیں (باری میں) الگ رکھیں اور جسے چاہیں اپنے پاس رکھیں اور جسے آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) نے کنارے کر دیا ہو (آپ صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم کو اختیار ہے) اگر اُسے آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم پھر) اپنے پاس بلانا چاہیں تو آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) پر کچھ مضائقہ نہیں اس طریقے میں اس بات کی زیادہ توقع ہے کہ ان سب کی آنکھیں ٹھنڈی رہیں گی اور وہ غمگین نہیں ہوں گی اور وہ سب اس سے راضی رہیں گی جو آپ اُن کو عطا فرمائیں اور (لوگو!) اللہ جانتا ہے جو کچھ تمھارے دلوں میں ہے اور اللہ خوب جاننے والا بڑا حلم والا ہے۔',
      'تاسو (صلی الله علیه وعلی آله واصحابه وسلم) له هغو (مېرمنو) چې چا ته وغواړئ (په نوبت کې) جلا یې وساتئ، او چې چا ته وغواړئ له ځان سره یې وساتئ؛ او چا ته چې تاسو (صلی الله علیه وعلی آله واصحابه وسلم) غاړه کړې وي، (اختیار لرئ) که یې (بیا) خپل لوري ته رابلل وغواړئ، نو پر تاسو څه باک نشته؛ په دې طریقه کې ډېره هیله ده چې د ټولو سترګې به یې یخې وي، خپه به نه وي، او ټولې به په هغه څه راضي وي چې تاسو یې ورکوئ؛ او (ای خلکو!) الله پوهېږي چې څه ستاسو په زړونو کې دي؛ او الله ښه پوه، ډېر زغمناک دی.')
    V(b, 33, 52, 'اس کے بعد آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کے لیے دوسری عورتیں حلال نہیں اور نہ یہ کہ آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) بدل لیں اُن کی جگہ دوسری بیویاں اگرچہ آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کو اُن کا حسن کتنا ہی بھلا لگے سوائے اُن (کنیزوں) کے جو آپ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کی ملکیت میں ہیں اور اللہ ہر شے پر نگہبان ہے۔',
      'له دې وروسته ستاسو (صلی الله علیه وعلی آله واصحابه وسلم) لپاره نورې ښځې حلالې نه دي، او نه دا چې د هغوی پر ځای نورې مېرمنې بدلې کړئ، که څه هم د هغوی ښکلا تاسو (صلی الله علیه وعلی آله واصحابه وسلم) ته هر څومره ښه ښکاره شي، پرته له هغو (وینځو) چې ستاسو (صلی الله علیه وعلی آله واصحابه وسلم) په ملکیت کې دي؛ او الله پر هر شي څارونکی دی.')
    V(b, 33, 53, 'اے ایمان والو! نبی (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کے گھروں میں نہ داخل ہوا کرو سوائے اس کے کہ تمھیں کھانے کے لیے اجازت دی جائے (وہ بھی اس طرح کہ) اُس کے تیار ہونے کے انتظار میں نہ بیٹھے رہو لیکن جب تمھیں بلایا جائے تو داخل ہو جاؤ پھر جب کھانا کھا چکو تو منتشر ہو جاؤ اور باتوں میں لگے بیٹھے نہ رہو بے شک تمھارا یہ (طرزِ عمل) نبی (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کو تکلیف پہنچاتا ہے تو وہ (کہتے ہوئے) تم سے حیا فرماتے ہیں اور اللہ حق (بات کہنے) کے معاملے میں لحاظ نہیں فرماتا اور جب تمھیں ان (ازواجِ مطہرات) سے کچھ مانگنا ہو تو پردہ کے پیچھے سے مانگو یہ تمھارے دلوں اور ان کے دلوں کے لیے زیادہ پاکیزگی کا باعث ہے اور تمھارے لیے (ہرگز) جائز نہیں کہ تم رسول اللہ (صلی اللہ علیہ وعلیٰ آلہٖ واصحابہٖ وسلم) کو تکلیف پہنچاؤ اور نہ یہ (جائز ہے) کہ تم اُن کے بعد ان کی ازواج (مطہرات) سے کبھی بھی نکاح کرو بے شک یہ اللہ کے نزدیک بہت بڑا (گناہ) ہے۔',
      'ای مؤمنانو! د نبي (صلی الله علیه وعلی آله واصحابه وسلم) کورونو ته مه ننوځئ مګر دا چې د خوړو لپاره اجازه درکړل شي، (هغه هم داسې چې) د هغو د تیارېدو په انتظار کې ناست پاتې نه شئ؛ خو کله چې وبلل شئ، نو ننوځئ، بیا چې خواړه مو وخوړل، نو خپاره شئ، او په خبرو بوخت ناست مه پاتې کېږئ؛ بې‌شکه ستاسو دا (چلند) نبي (صلی الله علیه وعلی آله واصحابه وسلم) ته تکلیف رسوي، نو هغه له تاسو (د ویلو) حیا کوي؛ او الله د حق (خبرې ویلو) په چاره کې لحاظ نه کوي؛ او کله چې له هغوی (پاکو مېرمنو) څخه کوم شی غواړئ، نو د پردې تر شا یې وغواړئ؛ دا ستاسو د زړونو او د هغوی د زړونو لپاره د زیاتې پاکۍ لامل دی؛ او ستاسو لپاره (هېڅکله) روا نه ده چې رسول الله (صلی الله علیه وعلی آله واصحابه وسلم) ته تکلیف ورسوئ، او نه دا (روا ده) چې له هغه وروسته د هغه له مېرمنو (پاکو مېرمنو) سره کله هم نکاح وکړئ؛ بې‌شکه دا د الله په وړاندې ډېره لویه (ګناه) ده.')
    V(b, 33, 54, 'اگر تم کسی چیز کو ظاہر کرو یا اسے چھپاؤ تو بے شک اللہ ہر شے کو خوب جاننے والا ہے۔',
      'که تاسو کوم شی ښکاره کړئ یا یې پټ کړئ، نو بې‌شکه الله په هر شي ښه پوه دی.')
    BOOK.save(120, [(12, rec(b, 12, 120, 120, pages_=[116, 117]))], issues=[{'id': 'mq12-pdf120', 'unit': 12, 'printedPage': 117,
               'description': 'Verse 33:51 begins on the last two lines of p.116; recorded here. The lower Urdu lines of p.117 are badly faded in the scan; read with contrast enhancement. Ruku sign (۶) not reproduced.'}])


